fn matches_old_implementation() {
    let alphabet: &[&str] = &["a", " ", "\t", "=", "\"", "\\", "[", "]", "n", "é"];
    for len in 0..=8u32 {
        let total = alphabet.len().pow(len);
        for mut code in 0..total {
            let mut line = String::new();
            for _ in 0..len {
                line.push_str(alphabet[code % alphabet.len()]);
                code /= alphabet.len();
            }
            let new: Vec<_> = logscan::tokenize(&line).map(|r| r.map(|t| format!("{t:?}"))).collect();
            let old: Vec<_> = old::tokenize(&line).map(|r| r.map(|t| format!("{t:?}"))).collect();
            assert_eq!(new, old, "line {line:?}");
